// Organised settings, reminder cards and clocks. Shares the existing native IPC contract.
fn section(title:&str)->AnyElement{div().mt_3().mb_1().text_size(px(12.)).font_weight(FontWeight::SEMIBOLD).text_color(t::text_dim()).child(title.to_owned()).into_any_element()}
fn mix_ui(a:gpui::Rgba,b:gpui::Rgba,k:f32)->gpui::Rgba{gpui::Rgba{r:a.r+(b.r-a.r)*k,g:a.g+(b.g-a.g)*k,b:a.b+(b.b-a.b)*k,a:1.}}
fn page_rows(page:usize,state:&Value,view:&SettingsApp,cx:&mut Context<SettingsApp>)->Vec<AnyElement>{match page{
 0=>vec![section("启动与窗口"),toggle_row("AutoStart","开机自动启动","登录后驻留托盘。",flag(state,"AutoStart",false),view),toggle_row("AlwaysOnTop","始终置顶","灵动岛显示在其他窗口上方。",flag(state,"AlwaysOnTop",true),view),toggle_row("HideWhenPaused","音乐暂停后隐藏","有计时器等活动时继续显示当前组件。",flag(state,"HideWhenPaused",true),view)],
 1=>{let mut rows=vec![section("尺寸与交互"),slider_row("CompactWidth","固定胶囊宽度","自适应关闭时使用此宽度。",140.,480.,"px",slider_value(state,"CompactWidth",view,260.),view,cx),toggle_row("AutoCompactWidth","歌词长度自适应宽度","按歌词实际宽度平滑伸缩。",flag(state,"AutoCompactWidth",false),view)];if flag(state,"AutoCompactWidth",false){rows.push(slider_row("AutoCompactMaxWidth","自适应宽度上限","只约束歌词自适应，不改变展开卡片尺寸。",140.,480.,"px",slider_value(state,"AutoCompactMaxWidth",view,420.),view,cx));}rows.extend([toggle_row("SwipeActivities","左右滑动胶囊切换","默认关闭。开启后按住收起胶囊或展开卡片左右拖动切换；旁边的圆形组件始终可点击切换。",flag(state,"SwipeActivities",false),view),toggle_row("HoverExpand","悬停展开","鼠标经过时展开当前组件。",flag(state,"HoverExpand",false),view),toggle_row("ClickAnywhereExpand","点击任意区域展开","展开当前选中的组件。",flag(state,"ClickAnywhereExpand",true),view),toggle_row("Floating","自由悬浮","允许移动灵动岛位置。",flag(state,"Floating",false),view),toggle_row("MusicClickOpenApp","点击封面或歌名打开播放器","仅影响音乐卡片。",flag(state,"MusicClickOpenApp",false),view),action_row("resetAppearance","恢复尺寸与位置","恢复胶囊尺寸、字号和固定位置。","恢复",view,cx)]);rows},
 2=>{let position=state["position"].as_f64().unwrap_or(0.);vec![section("显示"),slider_row("FontSize","歌词字号","同时应用于收起胶囊与音乐卡片。",11.,17.,"px",slider_value(state,"FontSize",view,12.5),view,cx),toggle_row("WordHighlight","歌词进度涂色","随演唱进度突出当前歌词。",flag(state,"WordHighlight",true),view),toggle_row("CompactTranslation","胶囊显示翻译","原文在上、翻译在下。",flag(state,"CompactTranslation",true),view),toggle_row("ChineseTwoLine","中文双行模式","没有翻译时，下面显示较小的下一句。",flag(state,"ChineseTwoLine",false),view),toggle_row("Translation","展开卡片显示翻译","有翻译时优先显示翻译。",flag(state,"Translation",true),view),section("时间同步"),info_row("当前来源",text(state,"lyricSource","等待获取"),text(state,"timeline","等待播放器")),slider_row("OffsetMilliseconds","歌词偏移","正数提前，负数延后。",-5000.,5000.,"ms",slider_value(state,"OffsetMilliseconds",view,0.),view,cx),calibrate_row(position,view,cx)]},
 3=>{let mut rows=vec![theme_row(state,cx),section("配色")];let mut colors=legacy_page_rows(0,state,view,cx).into_iter().skip(10).collect::<Vec<_>>();colors.pop();colors.pop();rows.extend(colors);rows.push(section("动效"));rows.extend(legacy_page_rows(1,state,view,cx));rows},
 4=>legacy_page_rows(3,state,view,cx),5=>{let mut rows=legacy_page_rows(6,state,view,cx);rows.push(section("设备"));rows.push(toggle_row("DeviceRemindersEnabled","设备连接提醒","U 盘、USB 设备和便携设备接入时显示横幅。默认关闭。",flag(state,"DeviceRemindersEnabled",false),view));rows.push(device_test_row(cx));rows},
 6=>{let mut rows=vec![info_row("音效与音量","内置短音已提高基础响度","以下滑块只调整点屿，不修改 Windows 系统音量。0% 为静音，可单独试听。")];rows.extend(sound_rows("Notification","通知音效","收到应用通知时播放。",state,view,cx));rows.push(section("待办与计时器"));rows.extend(sound_rows("Todo","提醒音效","待办到期、计时完成或番茄钟切换阶段时播放。",state,view,cx));rows.push(section("设备连接"));rows.extend(sound_rows("Device","设备音效","设备连接或移除横幅出现时播放。",state,view,cx));rows},
 7=>new_todo_rows(state,view,cx),8=>timer_rows(state,view,cx),9=>legacy_page_rows(4,state,view,cx),_=>legacy_page_rows(5,state,view,cx)}}
fn palette_row(view:&SettingsApp,cx:&mut Context<SettingsApp>)->AnyElement{let mut row=div().flex().items_center().gap_2();for value in ["#F3D79B","#E8B7C9","#B7DBCB","#C9BCE5","#B5CFEA","#EDC3A7"]{let selected=view.todo_color==value;row=row.child(div().id(SharedString::from(format!("todo-color-{value}"))).w(px(28.)).h(px(28.)).rounded(px(14.)).bg(t::parse(value)).border_2().border_color(if selected{t::accent()}else{t::hairline()}).cursor_pointer().child(if selected{"✓"}else{""}).text_color(rgb(0x273039)).on_click(cx.listener(move|view,_,_,cx|{view.todo_color=value.into();cx.notify();})));}div().flex().flex_col().gap_2().child(div().text_size(px(11.)).text_color(t::text_dim()).child("卡片颜色")).child(row).into_any_element()}
fn todo_settings_rows(state:&Value,view:&SettingsApp,cx:&mut Context<SettingsApp>)->Vec<AnyElement>{let mut rows=vec![button_row("todo-settings-back","待办设置","列表偏好与提醒行为。","返回清单",cx,|v,cx|{v.todo_settings=false;cx.notify();}),toggle_row("TodoRemindersEnabled","到期提醒","独立于应用通知总开关；暂停通知会暂时抑制提醒。",flag(state,"TodoRemindersEnabled",true),view),toggle_row("TodoIslandEnabled","在灵动岛显示待办组件","有未完成项目时，可切换到待办胶囊。",flag(state,"TodoIslandEnabled",true),view),color_row("TodoDefaultColor","新待办的默认颜色",state,view,cx)];if view.picker.as_ref().is_some_and(|p|p.key=="TodoDefaultColor"){rows.push(picker_panel(view,cx));}rows.push(button_row("todo-audio-link","提醒音量与音色","集中在音效页调整。","打开音效",cx,|v,cx|{v.page=6;cx.notify();}));rows.push(info_row("提醒方式","保存在本机","应用关闭时不在后台唤醒；重新打开后检查尚未提醒的项目。每日待办只提醒当天。"));rows}
fn ordinal(s:&str)->Option<i64>{let p=s.split('-').map(|p|p.parse::<i64>().ok()).collect::<Option<Vec<_>>>()?;if p.len()!=3{return None}let(y,m,d)=(p[0],p[1],p[2]);if !(1..=12).contains(&m)||!(1..=31).contains(&d){return None}let before=y-1;let mut days=before*365+before/4-before/100+before/400;let months=[31,28,31,30,31,30,31,31,30,31,30,31];for i in 0..(m-1)as usize{days+=months[i];}if m>2&&(y%400==0||(y%4==0&&y%100!=0)){days+=1;}Some(days+d)}
fn todo_matches(todo:&Value,filter:usize,state:&Value)->bool{let done=todo["completed"].as_bool().unwrap_or(false);if done{return false}let date=todo["date"].as_str().unwrap_or("");let today=text(state,"today","");let time=todo["time"].as_str().unwrap_or("");let now=text(state,"now","");let daily=todo["daily"].as_bool().unwrap_or(false);let overdue=if daily{date<=today&&time<now}else{date<today||(date==today&&time<now)};match filter{1=>!overdue,2=>overdue,3=>date==today||(daily&&date<=today),4=>daily&&date<=today||ordinal(date).zip(ordinal(today)).is_some_and(|(d,t)|d>=t&&d<t+7),_=>true}}
fn macaron_todo(todo:&Value,state:&Value,cx:&mut Context<SettingsApp>)->AnyElement{let id=todo["id"].as_str().unwrap_or("").to_owned();let edit=id.clone();let toggle=id.clone();let done=todo["completed"].as_bool().unwrap_or(false);let color=t::parse(todo["color"].as_str().unwrap_or("#F3D79B"));let dark=t::base().r<0.3;let bg=if done{t::field()}else{mix_ui(t::base(),color,if dark{0.15}else{0.25})};let mut meta=format!("{} {}{}",todo["date"].as_str().unwrap_or(""),todo["time"].as_str().unwrap_or(""),if todo["daily"]==true{" · 每天"}else{""});if !done&&todo_matches(todo,2,state){meta.push_str(" · 已过期");}
 let mut text_col=div().id(SharedString::from(format!("todo-open-{id}"))).flex().flex_col().flex_1().gap_1().cursor_pointer().child(div().text_size(px(15.)).font_weight(FontWeight::MEDIUM).text_color(if done{t::text_faint()}else{t::text()}).child(todo["title"].as_str().unwrap_or("待办").to_owned()));if let Some(content)=todo["content"].as_str().filter(|s|!s.is_empty()){text_col=text_col.child(div().text_size(px(11.5)).text_color(t::text_dim()).child(content.to_owned()));}text_col=text_col.child(div().text_size(px(11.5)).text_color(t::text_faint()).child(meta)).on_click(cx.listener(move|v,_,_,cx|v.open_todo_form(Some(edit.clone()),cx)));
 div().id(SharedString::from(format!("todo-{id}"))).flex().items_center().gap_4().px_4().py_4().rounded(px(20.)).bg(bg).child(div().w(px(3.)).h(px(43.)).rounded(px(2.)).bg(if done{t::text_faint()}else{color})).child(text_col).child(div().id(SharedString::from(format!("todo-toggle-{id}"))).w(px(25.)).h(px(25.)).rounded(px(13.)).border_2().border_color(if done{t::text_faint()}else{mix_ui(t::base(),color,0.65)}).bg(if done{t::text_faint()}else{bg}).flex().items_center().justify_center().text_color(t::base()).child(if done{"✓"}else{""}).cursor_pointer().active(|s|s.opacity(0.6)).on_click(cx.listener(move|v,_,_,cx|{send_todo(&v.shared,"todoComplete",json!({"id":toggle,"completed":!done}),cx);cx.notify();}))).into_any_element()
}
fn new_todo_rows(state:&Value,view:&SettingsApp,cx:&mut Context<SettingsApp>)->Vec<AnyElement>{if view.todo_settings{return todo_settings_rows(state,view,cx)}let todos=state["todos"].as_array().cloned().unwrap_or_default();let remaining=todos.iter().filter(|t|t["completed"]!=true).count();let completed=todos.len()-remaining;let mut rows=vec![div().flex().items_center().justify_between().child(div().text_size(px(14.)).text_color(t::text_dim()).child(format!("{remaining} 项待完成 · 共 {} 项",todos.len()))).child(div().flex().gap_2().child(small_button("todo-new".into(),"＋ 新建",cx.listener(|v,_,_,cx|v.open_todo_form(None,cx)))).child(div().id("todo-gear").w(px(36.)).h(px(36.)).rounded(px(18.)).bg(t::surface()).flex().items_center().justify_center().cursor_pointer().text_size(px(18.)).child("⚙").on_click(cx.listener(|v,_,_,cx|{v.todo_settings=true;cx.notify();})))).into_any_element()];
 let mut filters=div().flex().flex_wrap().gap_2();for(i,label)in ["全部","进行中","已过期","今天","最近 7 天"].iter().enumerate(){let active=view.todo_filter==i;filters=filters.child(div().id(("todo-filter",i)).px_3().py_2().rounded(px(13.)).bg(if active{t::surface_hi()}else{t::surface()}).text_size(px(12.)).text_color(if active{t::text()}else{t::text_dim()}).cursor_pointer().child((*label).to_owned()).on_click(cx.listener(move|v,_,_,cx|{v.todo_filter=i;cx.notify();})));}rows.push(filters.into_any_element());if view.todo_form_open{rows.push(todo_form(view,cx));if let Some(id)=view.todo_editing.clone(){rows.push(button_row("todo-delete-edit","移除待办","删除此条待办。","删除",cx,move|v,cx|{send_todo(&v.shared,"todoDelete",json!({"id":id}),cx);v.close_todo_form(cx);}));}}
 let mut list=todos.iter().filter(|t|todo_matches(t,view.todo_filter,state)).collect::<Vec<_>>();list.sort_by_key(|t|format!("{} {}",t["date"],t["time"]));if list.is_empty(){rows.push(info_row("清单已整理好","此分类下没有待办","点击右上角 ＋ 添加下一件要做的事。"));}for t in list{rows.push(macaron_todo(t,state,cx));}if completed>0{rows.push(button_row("todo-completed","已完成",&format!("{completed} 项"),if view.todo_completed_open{"收起"}else{"展开"},cx,|v,cx|{v.todo_completed_open=!v.todo_completed_open;cx.notify();}));if view.todo_completed_open{for t in todos.iter().filter(|t|t["completed"]==true){rows.push(macaron_todo(t,state,cx));}}}if let Some(error)=state["todoError"].as_str(){rows.push(info_row("待办存储异常","原文件已保留",error));}rows}
include!("timer_ui.rs");
impl SettingsApp{fn create_timer(&mut self,cx:&mut Context<Self>){let number=|f:&Entity<TextField>|f.read(cx).text().trim().parse::<u64>().ok();let (Some(duration),Some(focus),Some(rest),Some(rounds))=(number(&self.timer_duration),number(&self.timer_focus),number(&self.timer_rest),number(&self.timer_rounds))else{if let Ok(mut s)=self.shared.lock(){s.message="请使用整数填写计时时长与轮数".into();}cx.notify();return};self.timer_new=false;send_todo(&self.shared,"timerCreate",json!({"mode":self.timer_mode,"name":self.timer_name.read(cx).text(),"duration":duration,"focus":focus,"rest":rest,"rounds":rounds}),cx);}}
#[cfg(test)]mod tools_ui_tests{use super::{ordinal,todo_matches};use serde_json::json;#[test]fn date_ranges_cross_year_and_leap_day(){assert_eq!(ordinal("2027-01-01").unwrap()-ordinal("2026-12-31").unwrap(),1);assert_eq!(ordinal("2028-03-01").unwrap()-ordinal("2028-02-28").unwrap(),2);}#[test]fn daily_tasks_can_appear_today_but_completed_items_do_not(){let s=json!({"today":"2026-10-16","now":"12:00"});let mut t=json!({"date":"2026-01-01","time":"09:00","daily":true,"completed":false});assert!(todo_matches(&t,3,&s));assert!(todo_matches(&t,2,&s));t["completed"]=json!(true);assert!(!todo_matches(&t,0,&s));}}

fn device_test_row(cx:&mut Context<SettingsApp>)->AnyElement{let mut buttons=div().flex().flex_wrap().gap_2();for(kind,connected,label)in[("disk",true,"U 盘连接"),("phone",true,"手机连接"),("disk",false,"设备移除")]{buttons=buttons.child(small_button(SharedString::from(format!("device-test-{kind}-{connected}")),label,cx.listener(move|v,_,_,cx|send_todo(&v.shared,"devicePreview",json!({"kind":kind,"connected":connected}),cx))));}card("device-tests","测试连接提醒","显示示例弹窗；无需插入真实设备。音效可在音效页试听。").child(buttons).into_any_element()}
